def f2(g):
    g=[row[:] for row in g]; h=len(g); w=len(g[0])
    vals=sorted({x for row in g for x in row})
    # base = most common, marker = other
    from collections import Counter
    c=Counter(x for row in g for x in row)
    base=c.most_common(1)[0][0]
    marker=[v for v in vals if v!=base][0]
    fill=3
    import copy
    g=[row[:] for row in g]
    orig=[row[:] for row in g]
    for i in range(h):
        cols=[j for j in range(w) if orig[i][j]==marker]
        for a in range(len(cols)-1):
            if all(orig[i][j]==base for j in range(cols[a]+1,cols[a+1])):
                for j in range(cols[a]+1,cols[a+1]): g[i][j]=fill
    for j in range(w):
        rws=[i for i in range(h) if orig[i][j]==marker]
        for a in range(len(rws)-1):
            if all(orig[i][j]==base for i in range(rws[a]+1,rws[a+1])):
                for i in range(rws[a]+1,rws[a+1]): g[i][j]=fill
    return g
